import{_ as c}from"./chunks/ArticleMetadata.DmiB8yLO.js";import{_ as i,B as d,o,c as k,j as a,a as r,E as m,w as h,b as _,e as u,a4 as v}from"./chunks/framework.CW-6O5Zu.js";import"./chunks/theme.CK5G8gjT.js";const S=JSON.parse('{"title":"在开发环境中使用服务发现","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/courses/开发者必备的 Docker 实践指南/实践之路：在开发环境中使用服务发现.md","filePath":"knowledge/courses/开发者必备的 Docker 实践指南/实践之路：在开发环境中使用服务发现.md","lastUpdated":1776396922000}'),b={name:"knowledge/courses/开发者必备的 Docker 实践指南/实践之路：在开发环境中使用服务发现.md"};function g(s,e,Z,f,O,y){const l=c,t=d("ClientOnly");return o(),k("div",null,[e[0]||(e[0]=a("h3",{id:"本资源由-itjc8-com-收集整理",tabindex:"-1"},[r("本资源由 itjc8.com 收集整理 "),a("a",{class:"header-anchor",href:"#本资源由-itjc8-com-收集整理","aria-label":'Permalink to "本资源由 itjc8.com 收集整理"'},"​")],-1)),e[1]||(e[1]=a("h1",{id:"在开发环境中使用服务发现",tabindex:"-1"},[r("在开发环境中使用服务发现 "),a("a",{class:"header-anchor",href:"#在开发环境中使用服务发现","aria-label":'Permalink to "在开发环境中使用服务发现"'},"​")],-1)),m(t,null,{default:h(()=>{var n,p;return[(((n=s.$frontmatter)==null?void 0:n.aside)??!0)&&(((p=s.$frontmatter)==null?void 0:p.showArticleMetadata)??!0)?(o(),_(l,{key:0,article:s.$frontmatter,readTime:2,words:343},null,8,["article"])):u("",!0)]}),_:1}),e[2]||(e[2]=v(`<p>服务发现应用是很多服务化系统的组成部分，所以在开发、测试环境中也就有必要配备一套服务发现体系来配合我们的开发、测试工作。在这一小节里，我们就来谈谈如何在 Docker 环境下部署服务发现应用。</p><h2 id="使用-docker-compose-模拟-zookeeper-集群" tabindex="-1">使用 Docker Compose 模拟 Zookeeper 集群 <a class="header-anchor" href="#使用-docker-compose-模拟-zookeeper-集群" aria-label="Permalink to &quot;使用 Docker Compose 模拟 Zookeeper 集群&quot;">​</a></h2><p>实现服务发现的方法有很多种，其中较为常见的一种是利用分布式注册中心，解决服务之间协调的问题。</p><p>在众多注册中心应用中，Zookeeper 是较为常见和常用的一款程序，这里我们就以 Zookeeper 为例，介绍如何使用 Docker 搭建 Zookeeper 的运行环境。</p><h3 id="设计目录结构" tabindex="-1">设计目录结构 <a class="header-anchor" href="#设计目录结构" aria-label="Permalink to &quot;设计目录结构&quot;">​</a></h3><p>由于 Zookeeper 的运行并不需要太多的关注配置和调整，这里我们就以最基础的形式来设计 Docker Compose 项目的结构。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>└─ project</span></span>
<span class="line"><span>   ├─ bin</span></span>
<span class="line"><span>   │  └─ compose.sh</span></span>
<span class="line"><span>   └─ compose</span></span>
<span class="line"><span>      └─ docker-compose.yml</span></span></code></pre></div><p>为了方便日常操作，我们依然编写了 <a href="http://compose.sh" target="_blank" rel="noreferrer">compose.sh</a> 这个脚本来辅助我们控制 Docker Compose 项目。</p><h3 id="编写-docker-compose-yml" tabindex="-1">编写 docker-compose.yml <a class="header-anchor" href="#编写-docker-compose-yml" aria-label="Permalink to &quot;编写 docker-compose.yml&quot;">​</a></h3><p>很多读者会问到一个问题，怎么样才能通过 Docker 的虚拟化技术实现在一个机器上模拟出多台机器的效果。或者说一个我们这里会涉及的具体问题，如何只用一个 Docker 来模拟一个高可用的 Zookeeper 集群。</p><p>我们知道，要实现 Zookeeper 的高可用，至少需要三个 Zookeeper 节点进行协作，所以这里我们用三个单独的 Docker Compose 服务定义来分别定义这三个节点。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>version: &#39;3&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>services:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  zk1:</span></span>
<span class="line"><span>    image: zookeeper:3.4</span></span>
<span class="line"><span>    restart: always</span></span>
<span class="line"><span>    hostname: zk1</span></span>
<span class="line"><span>    environment:</span></span>
<span class="line"><span>      ZOO_MY_ID: 1</span></span>
<span class="line"><span>      ZOO_SERVERS: server.1=0.0.0.0:2888:3888 server.2=zk2:2888:3888 server.3=zk3:2888:3888</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - 2181:2181</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  zk2:</span></span>
<span class="line"><span>    image: zookeeper:3.4</span></span>
<span class="line"><span>    restart: always</span></span>
<span class="line"><span>    hostname: zk2</span></span>
<span class="line"><span>    environment:</span></span>
<span class="line"><span>      ZOO_MY_ID: 2</span></span>
<span class="line"><span>      ZOO_SERVERS: server.1=zk1:2888:3888 server.2=0.0.0.0:2888:3888 server.3=zk3:2888:3888</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - 2182:2181</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  zk3:</span></span>
<span class="line"><span>    image: zookeeper:3.4</span></span>
<span class="line"><span>    restart: always</span></span>
<span class="line"><span>    hostname: zk3</span></span>
<span class="line"><span>    environment:</span></span>
<span class="line"><span>      ZOO_MY_ID: 3</span></span>
<span class="line"><span>      ZOO_SERVERS: server.1=zk1:2888:3888 server.2=zk2:2888:3888 server.3=0.0.0.0:2888:3888</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - 2183:2181</span></span></code></pre></div><p>在这个 Docker Compose 项目中，我们定义的三个 Zookeeper 服务都直接使用了官方制作的 zookeeper 镜像。</p><p>在这个镜像里，我们可以留意定制 ZOO_MY_ID 和 ZOO_SERVERS 这两个环境变量。这两个变量主要是用来识别 Zookeeper 集群中不同 Zookeeper 程序的。</p><p>其中 ZOO_MY_ID 是 Zookeeper 在集群中的编号，而 ZOO_SERVERS 用来定义集群中的所有 Zookeeper 及它们的连接方式。</p><p>我们以 zk1 这个服务为例来解释一下 ZOO_SERVERS 的定义方法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>server.1=0.0.0.0:2888:3888 server.2=zk2:2888:3888 server.3=zk3:2888:3888</span></span></code></pre></div><p>我们可以在 ZOO_SERVERS 中定义所有处于 Zookeeper 集群中的程序，通过空格来间隔它们。而每个服务的的定义形式为 <code>server.[id]=[host]:[port]:[port]</code>，所以就有了上面例子中我们看到的样子。</p><p>在这个例子里，我们描述了三个 Zookeeper 程序的连接地址。</p><p>由于每个容器都有独立的端口表，所以即使这些程序都运行在一个主机里，我们依然不需要担心，它们会造成端口的冲突。所以这里我们直接使用默认的 2888 和 3888 来进行服务间的相互通信即可。</p><p>而在进行容器互联的过程中，我们可以通过 Docker 的解析机制，直接填入对应服务的名称替代它们的 IP 地址，也就是这个例子里的 zk2 和 zk3。</p><h3 id="重启机制" tabindex="-1">重启机制 <a class="header-anchor" href="#重启机制" aria-label="Permalink to &quot;重启机制&quot;">​</a></h3><p>在项目定义中，我们还注意到了 <code>restart: always</code> 这个配置，这个配置主要是用来控制容器的重启策略的。</p><p>这里的 always 指的是不论任何情况，容器出现问题后都会自动重启，也包括 Docker 服务本身在启动后容器也会自动启动。</p><p>另外，restart 还支持几种配置：</p><p>配置值</p><p>说明</p><p>no</p><p>不设重启机制</p><p>always</p><p>总是重启</p><p>on-failure</p><p>在异常退出时重启</p><p>unless-stopped</p><p>除非由停止命令结束，其他情况都重启</p><p>在实际使用中，我们可以根据需要选择不同的重启策略。</p><p>而这个项目里，我们希望 Zookeeper 能够一直健壮的运行，所以使用了 always 这个重启策略。</p><h2 id="启动项目" tabindex="-1">启动项目 <a class="header-anchor" href="#启动项目" aria-label="Permalink to &quot;启动项目&quot;">​</a></h2><p>一切就绪，我们就可以直接通过 Docker Compose 的命令来启动开发环境了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes one-dark-pro material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span># ./bin/compose.sh up -d</span></span></code></pre></div><h2 id="留言互动" tabindex="-1">留言互动 <a class="header-anchor" href="#留言互动" aria-label="Permalink to &quot;留言互动&quot;">​</a></h2><p>在这节中，我们展示了在开发中使用 Docker 部署服务发现工具的过程，下面就是大家自己动手进行实践的时候了。</p><p>本小节中的示例，已经更新到了：</p><p><a href="https://github.com/youmingdot/docker-book-for-developer-samples" target="_blank" rel="noreferrer">https://github.com/youmingdot/docker-book-for-developer-samples</a></p><p>大家可以在实践过程中的用其作为参考。</p><p>欢迎大家通过留言的方式说出你的实践之路。我会选出有代表性的优质留言，推荐给大家。</p><p>同时，如果大家在实践过程中遇到困难，或者有自己的实践心得要与大家分享，可以加入到这本小册的官方微信群中，参与对相关问题的讨论。</p>`,47))])}const E=i(b,[["render",g]]);export{S as __pageData,E as default};
